import{_ as t}from"./chunks/failure-clusters.DuMKYAYD.js";import{_ as a}from"./chunks/failure-cluster-triage.D6b2KKOa.js";import{_ as r,o as s,c as o,ak as n}from"./chunks/framework.sV-XtlWr.js";const y=JSON.parse('{"title":"Triage a run that went mostly red","description":"","frontmatter":{"title":"Triage a run that went mostly red","lang":"en-US"},"headers":[],"relativePath":"recipes/mass-failure.md","filePath":"recipes/mass-failure.md","lastUpdated":1788630071000}'),i={name:"recipes/mass-failure.md"};function l(d,e,h,c,u,g){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="forty-tests-are-red-—-where-do-i-start" tabindex="-1">Forty tests are red — where do I start? <a class="header-anchor" href="#forty-tests-are-red-—-where-do-i-start" aria-label="Permalink to &quot;Forty tests are red — where do I start?&quot;">​</a></h1><p>Almost never with forty bugs. A run that goes broadly red is usually two or three causes wearing forty costumes: an environment that didn&#39;t come up, an auth change, one shared component, one bad worker. The job is to collapse the list before reading any stack traces.</p><h2 id="_1-read-the-clusters-not-the-tests" tabindex="-1">1. Read the clusters, not the tests <a class="header-anchor" href="#_1-read-the-clusters-not-the-tests" aria-label="Permalink to &quot;1. Read the clusters, not the tests&quot;">​</a></h2><p>Failures sharing an <strong>error fingerprint</strong> are grouped automatically, so the run tells you <em>&quot;40 failures, 3 root causes&quot;</em> before you open anything.</p><figure><img src="'+t+'" alt="Failure clusters tab grouping failures by normalized error signature"><figcaption>The Failure clusters tab — one row per root cause, with error type, occurrence count, and triage status.</figcaption></figure><p>Fingerprinting masks the volatile parts of an error (timeouts and other numbers, UUIDs, URLs, the expected and received values of an assertion) so the same underlying failure groups across tests, spec files, and runs. It&#39;s always on and needs no configuration.</p><h2 id="_2-rule-out-the-boring-causes-first" tabindex="-1">2. Rule out the boring causes first <a class="header-anchor" href="#_2-rule-out-the-boring-causes-first" aria-label="Permalink to &quot;2. Rule out the boring causes first&quot;">​</a></h2><p>Before treating any cluster as a product bug, check the two heuristics on the run&#39;s failure groups:</p><ul><li><strong>Worker correlation</strong> — if a cluster&#39;s failures are concentrated on one worker, you&#39;re looking at a misbehaving worker, not forty broken tests.</li><li><strong>Flaky share</strong> — a cluster made up largely of known-flaky tests is noise riding on a bad run.</li></ul><p>An environment that never came up has a signature of its own: everything fails, fast, on a navigation or connection error. That&#39;s one cluster, one fix, and no test code involved.</p><h2 id="_3-triage-each-cluster-once" tabindex="-1">3. Triage each cluster once <a class="header-anchor" href="#_3-triage-each-cluster-once" aria-label="Permalink to &quot;3. Triage each cluster once&quot;">​</a></h2><p>A cluster page puts the whole investigation on one screen: the signature and resolution at the top, a <strong>Triage</strong> rail on the right that sets one status — open, resolved, or ignored — plus a note for the entire group, and collapsible evidence sections down the left. Forty tests, three decisions.</p><figure><img src="'+a+'" alt="A failure cluster page: signature, occurrence and affected-test counts, a resolution card marked Regressed, the triage rail with open/resolved/ignored and a note, and collapsed evidence sections for error message, alternative locators, environment diff, visual diff, DOM snapshot, test evidence and what changed"><figcaption>One cluster, one screen — occurrences and affected tests up top, the resolution history beside them, triage in the right rail, and every piece of evidence one click away on the left.</figcaption></figure><p>Clusters stay open across runs, so the next red build attaches to the same row rather than starting the conversation over.</p><h2 id="_4-confirm-the-fix-actually-landed" tabindex="-1">4. Confirm the fix actually landed <a class="header-anchor" href="#_4-confirm-the-fix-actually-landed" aria-label="Permalink to &quot;4. Confirm the fix actually landed&quot;">​</a></h2><p>When a later run executes every test a cluster covers and they all pass, Piwi records the fix — the run, the commit, and how long the cluster was open — with three separate verdicts, because they aren&#39;t the same claim. The run doesn&#39;t have to be a full one: re-running just the affected tests and seeing them all pass closes the cluster too.</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Means</th></tr></thead><tbody><tr><td><strong>Stopped failing</strong></td><td>The tests pass again. A flaky test can manage this by accident.</td></tr><tr><td><strong>Diagnosis verified</strong></td><td>Commits since the last failing run touched a file the <a href="./../ai-diagnosis.html#what-a-diagnosis-contains">suggested patch</a> named.</td></tr><tr><td><strong>Regressed</strong></td><td>A fix was recorded and the cluster is failing again.</td></tr></tbody></table><h2 id="optional-let-a-model-do-the-first-pass" tabindex="-1">Optional: let a model do the first pass <a class="header-anchor" href="#optional-let-a-model-do-the-first-pass" aria-label="Permalink to &quot;Optional: let a model do the first pass&quot;">​</a></h2><p>With <a href="./../ai-diagnosis.html">AI diagnosis</a> configured, each cluster gets an explanation read against your actual git diff since the last green run, and any suggested patch is validated against your source before it&#39;s shown. It&#39;s off by default and works with a local model — the point is that clustering has already decided <em>what</em> is worth diagnosing, so the model runs a few times per run, not forty.</p><p>Configuring an <strong>embedding</strong> role additionally merges clusters that are the same root cause phrased differently. Without one, clustering stays purely deterministic — still useful, just less aggressive about collapsing near-duplicates.</p><h2 id="other-ways-in" tabindex="-1">Other ways in <a class="header-anchor" href="#other-ways-in" aria-label="Permalink to &quot;Other ways in&quot;">​</a></h2><p><strong>From your agent.</strong> <code>get_failure_groups</code> over the <a href="./../mcp.html">MCP server</a> returns a run&#39;s failures grouped by cluster with the worker correlation included, and <code>get_test_case_context</code> pulls the evidence behind a single failure — steps, console, network, SCM diff. No install; the server is part of the dashboard.</p><p><strong>From a script.</strong> The same grouping is available over the REST API if you&#39;d rather post a summary into your own channel — see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>.</p><p><strong>Before anyone opens anything.</strong> Subscribe to the <code>cluster.new</code> <a href="./../notifications.html">notification</a> event instead of <code>run.failed</code>: you hear once when a genuinely new root cause appears, not on every red build, and the payload carries a sample error excerpt and the affected cases.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../ai-diagnosis.html">AI diagnosis &amp; failure clustering</a> — how fingerprints and semantic merging work</li><li><a href="./regression-or-flaky.html">Regression or flake?</a> — when it&#39;s one test rather than forty</li><li><a href="./../concepts.html">Core concepts</a> — <em>cluster</em>, <em>fingerprint</em>, <em>baseline</em></li></ul>',26)])])}const b=r(i,[["render",l]]);export{y as __pageData,b as default};
